using System;using System.IO;using System.Linq;using System.Collections.Generic;
class MockB {
 static int Main(string[] args){string input=args[Array.IndexOf(args,"-f")+1],output=args[Array.IndexOf(args,"-o")+1],log=args[Array.IndexOf(args,"-l")+1],root=Path.GetDirectoryName(output);Directory.CreateDirectory(root);string text=File.ReadAllText(input),state=Path.Combine(root,"mock-state.txt");var done=File.Exists(state)?File.ReadAllLines(state).ToDictionary(x=>x.Substring(0,6),x=>x.Substring(7)):new Dictionary<string,string>();
 if(text.Contains("DN390002")){var records=text.Split('\n').Select(x=>x.Trim()).Where(x=>x.StartsWith("VN390002")).ToList();foreach(string record in records){string cow=record.Substring(8,6),value=record.Substring(14);if(cow!="000001"&&cow!="000002")return 7;string reg=cow=="000001"?"SE-020201-1234":"SE-020201-1235";if(value!=Logic.Hdx(reg))return 8;done[cow]=value;}File.WriteAllLines(state,done.Select(x=>x.Key+"\t"+x.Value));File.WriteAllText(Path.Combine(root,"writes.txt"),string.Join("\n",records));File.WriteAllText(output,"");}
 else {if(!text.Contains("00300002050"))return 9;int reads=File.Exists(Path.Combine(root,"reads.txt"))?int.Parse(File.ReadAllText(Path.Combine(root,"reads.txt"))):0;reads++;File.WriteAllText(Path.Combine(root,"reads.txt"),reads.ToString());bool newlyB=root.Contains("freshB")&&reads>=2,unknown=root.Contains("unknown");var rows=new List<string>();for(int i=1;i<=3;i++){string cow=i.ToString("D6"),reg=i==1?"SE-020201-1234":i==2?"SE-020201-1235":"NO-041308-0967",old=done.ContainsKey(cow)?done[cow]:i==3?"578000000000001":"?",b=done.ContainsKey(cow)?"0":i==1?"12345":i==3?"98765":newlyB?"22222":"0";rows.Add(cow+"\t"+reg+"\t"+old+(unknown?"":"\t"+b));}File.WriteAllText(output,string.Join("\n",rows)+"\nZN\n");}File.WriteAllText(log,"mock only");return 0;}
}
